import{_ as o}from"./chunks/img_2326-portrait_1.DGqQCP4f.js";import{_ as e,o as i,c as l,aa as n}from"./chunks/framework.BAs_AphD.js";const t="/buildary-help-preview/media/cs/news/img_2321-portrait_1.png",c=JSON.parse('{"title":"Novinky v mobilní aplikaci 5.1.0","description":"","frontmatter":{"title":"Novinky v mobilní aplikaci 5.1.0","wiki":"cs:news:version_5.1.0"},"headers":[],"relativePath":"news/version_5-1-0.md","filePath":"news/version_5-1-0.md","lastUpdated":1793708206000}'),r={name:"news/version_5-1-0.md"};function s(k,a,v,u,m,p){return i(),l("div",null,[...a[0]||(a[0]=[n('<h1 id="novinky-v-mobilni-aplikaci-5-1-0" tabindex="-1">Novinky v mobilní aplikaci 5.1.0 <a class="header-anchor" href="#novinky-v-mobilni-aplikaci-5-1-0" aria-label="Permalink to &quot;Novinky v mobilní aplikaci 5.1.0&quot;">​</a></h1><p>Mobilní aplikace Buildary přináší další várku novinek, které vám usnadní práci přímo na stavbě. Nově můžete pracovat i bez připojení k internetu, vytvářet úkoly z fotografií, výkresů, mapy nebo přímo z elektronického stavebního deníku a využívat také nové možnosti práce s přílohami a notifikacemi.</p><p><strong>Management úkolů</strong></p><ul><li><a href="#zalozeni-ukolu-z-fotky">Založení úkolu z fotky</a></li><li><a href="#nova-zalozka-vykresy-a-mapa">Nová záložka „Výkresy a mapa“</a></li><li><a href="#zalozeni-ukolu-z-esd">Založení úkolu z ESD</a></li><li><a href="#souvisejici-ukoly">Související úkoly</a></li></ul><p><strong>Další novinky</strong></p><ul><li><a href="#offline-rezim">Offline režim</a></li><li><a href="#prohlizec-souboru-a-fotek">Prohlížeč souborů a fotek</a></li><li><a href="#ios-multiselect">iOS multiselect</a></li><li><a href="#pravidla-resitele-schvalovatele">Pravidla řešitele/schvalovatele</a></li><li><a href="#push-notifikace">Push notifikace</a></li></ul><h2 id="modul-management-ukolu" tabindex="-1">Modul MANAGEMENT ÚKOLŮ <a class="header-anchor" href="#modul-management-ukolu" aria-label="Permalink to &quot;Modul MANAGEMENT ÚKOLŮ&quot;">​</a></h2><div class="wiki-float wiki-float-right"><img src="'+t+'" alt="Nový úkol v mobilní aplikaci" width="250" data-no-zoom loading="lazy"></div><h3 id="zalozeni-ukolu-z-fotky" tabindex="-1">Založení úkolu z fotky <a class="header-anchor" href="#zalozeni-ukolu-z-fotky" aria-label="Permalink to &quot;Založení úkolu z fotky&quot;">​</a></h3><p>Vyfoťte problém přímo na místě a během pár vteřin z něj vytvořte úkol. Fotku můžete rovnou upravit, například zakreslit nebo popsat závadu. Zadávání úkolů je tak rychlejší a vyžaduje méně administrativy.</p><h3 id="nova-zalozka-vykresy-a-mapa" tabindex="-1">Nová záložka „Výkresy a mapa“ <a class="header-anchor" href="#nova-zalozka-vykresy-a-mapa" aria-label="Permalink to &quot;Nová záložka „Výkresy a mapa“ {#nova-zalozka-vykresy-a-mapa}&quot;">​</a></h3><p>Úkoly nyní můžete zakládat přímo z výkresové dokumentace nebo z mapového podkladu. Stačí označit konkrétní místo na výkresu nebo v mapě a úkol je rovnou provázaný s danou lokalitou. Přehled o tom, co se kde řeší, máte doslova na dosah ruky.</p><h3 id="zalozeni-ukolu-z-esd" tabindex="-1">Založení úkolu z ESD <a class="header-anchor" href="#zalozeni-ukolu-z-esd" aria-label="Permalink to &quot;Založení úkolu z ESD&quot;">​</a></h3><p>Elektronický stavební deník a úkoly jsou nyní propojené ještě těsněji. Nový úkol lze založit přímo ze záznamu v ESD, bez zbytečného přepisování informací.</p><h3 id="souvisejici-ukoly" tabindex="-1">Související úkoly <a class="header-anchor" href="#souvisejici-ukoly" aria-label="Permalink to &quot;Související úkoly&quot;">​</a></h3><p>V elektronickém stavebním deníku si nově zobrazíte i úkoly, které byly z konkrétního záznamu vytvořeny. Kompletní historie a návaznost jsou tak přehledně na jednom místě.</p><h2 id="dalsi-novinky-v-mobilni-aplikaci" tabindex="-1">Další novinky v mobilní aplikaci <a class="header-anchor" href="#dalsi-novinky-v-mobilni-aplikaci" aria-label="Permalink to &quot;Další novinky v mobilní aplikaci&quot;">​</a></h2><div class="wiki-float wiki-float-right"><img src="'+o+'" alt="Úkoly v mobilní aplikaci" width="250" data-no-zoom loading="lazy"></div><h3 id="offline-rezim" tabindex="-1">Offline režim <a class="header-anchor" href="#offline-rezim" aria-label="Permalink to &quot;Offline režim&quot;">​</a></h3><p>Práce na stavbě nekončí tam, kde končí signál. V mobilní aplikaci můžete nově pracovat i bez připojení k internetu – upravovat úkoly, které jste už dříve otevřeli, zakládat nové úkoly a přidávat k nim vyjádření. Jakmile se zařízení znovu připojí k síti, všechny změny se automaticky synchronizují.</p><h3 id="prohlizec-souboru-a-fotek" tabindex="-1">Prohlížeč souborů a fotek <a class="header-anchor" href="#prohlizec-souboru-a-fotek" aria-label="Permalink to &quot;Prohlížeč souborů a fotek&quot;">​</a></h3><p>Nový vestavěný prohlížeč umožňuje procházet soubory a fotografie přímo v aplikaci, bez nutnosti přepínat mezi aplikacemi nebo stahovat přílohy zvlášť.</p><h3 id="ios-multiselect" tabindex="-1">iOS multiselect <a class="header-anchor" href="#ios-multiselect" aria-label="Permalink to &quot;iOS multiselect&quot;">​</a></h3><p>Uživatelé iOS ocení možnost hromadně vybrat více fotek nebo souborů najednou. Přidávání příloh k úkolům je tak výrazně rychlejší.</p><h3 id="pravidla-resitele-schvalovatele" tabindex="-1">Pravidla řešitele/schvalovatele <a class="header-anchor" href="#pravidla-resitele-schvalovatele" aria-label="Permalink to &quot;Pravidla řešitele/schvalovatele&quot;">​</a></h3><p>Nová podpora pravidel umožňuje automatické přiřazení řešitele a schvalovatele úkolu. Výsledkem je méně ruční práce a jasně nastavené odpovědnosti v týmu.</p><h3 id="push-notifikace" tabindex="-1">Push notifikace <a class="header-anchor" href="#push-notifikace" aria-label="Permalink to &quot;Push notifikace&quot;">​</a></h3><p>O novém úkolu, změně nebo novém záznamu v ESD se dozvíte okamžitě, přímo na vašem mobilu, bez nutnosti aplikaci otevírat.</p><div class="clear"></div>',29)])])}const z=e(r,[["render",s]]);export{c as __pageData,z as default};
